function buildMinHeap(nums) {
  for (let end = 1; end < nums.length; end++) {     // nums[0..end-1] is already a heap
    let i = end;                                    // let nums[end] join it: sift up
    while (i > 0) {
      const parent = Math.floor((i - 1) / 2);
      if (nums[parent] <= nums[i]) break;
      [nums[parent], nums[i]] = [nums[i], nums[parent]];
      i = parent;
    }
  }
  return nums;
}

